<?php admin_page_start('Reviews','reviews','CONTENT & MARKETING','Customer','Reviews','Moderate verified-purchase reviews before they appear on product pages.'); ?>
<?php if($message):?><div class="app-alert admin-alert success"><?=htmlspecialchars($message,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($error):?><div class="app-alert admin-alert danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?>
<section class="app-panel admin-panel admin-card-pad"><div class="panel-heading"><div><p class="panel-kicker">MODERATION</p><h2>Customer reviews</h2><p class="admin-muted">Verified purchases can submit reviews. Nothing becomes public until you publish it.</p></div><div class="admin-filter-tabs"><a class="<?=$status===''?'is-active':''?>" href="<?=htmlspecialchars(route_url('admin/reviews.php'),ENT_QUOTES,'UTF-8')?>">All</a><?php foreach(['pending'=>'Pending','approved'=>'Published','hidden'=>'Hidden'] as $key=>$label):?><a class="<?=$status===$key?'is-active':''?>" href="<?=htmlspecialchars(route_url('admin/reviews.php').'?status='.$key,ENT_QUOTES,'UTF-8')?>"><?=$label?> · <?=number_format((int)($counts[$key]??0))?></a><?php endforeach;?></div></div>
<?php if(!$ready):?><div class="admin-empty-state"><strong>Reviews are not available yet.</strong><p>Apply commerce migration 034.</p></div><?php elseif(!$rows):?><div class="admin-empty-state"><strong>No reviews in this view.</strong><p>New verified-purchase reviews will appear here for moderation.</p></div><?php else:?><div class="admin-card-list"><?php foreach($rows as $r):?><article class="app-panel admin-panel admin-card-pad"><div class="panel-heading"><div><p class="panel-kicker"><?=htmlspecialchars(strtoupper((string)$r['status']),ENT_QUOTES,'UTF-8')?> · <?=str_repeat('★',max(1,min(5,(int)$r['rating'])))?></p><h3><?=htmlspecialchars((string)$r['product_name'],ENT_QUOTES,'UTF-8')?></h3><p class="admin-muted">By <?=htmlspecialchars((string)$r['username'],ENT_QUOTES,'UTF-8')?><?php if(!empty($r['order_number'])):?> · Order <?=htmlspecialchars((string)$r['order_number'],ENT_QUOTES,'UTF-8')?><?php endif;?> · <?=htmlspecialchars(web_local_datetime($r['updated_at']??$r['created_at']),ENT_QUOTES,'UTF-8')?></p></div><a class="app-button admin-button secondary" href="<?=htmlspecialchars(route_url('product.php').'?slug='.rawurlencode((string)$r['product_slug']),ENT_QUOTES,'UTF-8')?>" target="_blank" rel="noopener">View product</a></div><?php if(!empty($r['title'])):?><h3><?=htmlspecialchars((string)$r['title'],ENT_QUOTES,'UTF-8')?></h3><?php endif;?><p><?=nl2br(htmlspecialchars((string)$r['body'],ENT_QUOTES,'UTF-8'))?></p><div class="admin-inline-actions"><?php if($r['status']!=='approved'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="approve"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="return_status" value="<?=htmlspecialchars($status,ENT_QUOTES,'UTF-8')?>"><button class="app-button admin-button primary" type="submit">Publish</button></form><?php endif;?><?php if($r['status']!=='hidden'):?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="hide"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="return_status" value="<?=htmlspecialchars($status,ENT_QUOTES,'UTF-8')?>"><button class="app-button admin-button secondary" type="submit">Hide</button></form><?php endif;?><form method="post" onsubmit="return confirm('Delete this review permanently?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input type="hidden" name="return_status" value="<?=htmlspecialchars($status,ENT_QUOTES,'UTF-8')?>"><button class="app-button admin-button danger" type="submit">Delete</button></form></div></article><?php endforeach;?></div><?php endif;?></section>
<?php admin_page_end(); ?>
